70	    private Boolean bulkSignupWarning;
71	
72	    @OneToMany(cascade = CascadeType.ALL, mappedBy = "owner", fetch = FetchType.EAGER)
73	    private Set<Pet> pets;
74	
75	    public String getAddress() {
76	        return this.address;
77	    }
78	
79	    public void setAddress(String address) {
80	        this.address = address;
81	    }
82	
83	    public String getCity() {
84	        return this.city;
85	    }
86	
87	    public void setCity(String city) {
88	        this.city = city;
89	    }
90	
91	    public String getTelephone() {
92	        return this.telephone;
93	    }
94	
95	    public void setTelephone(String telephone) {
96	        this.telephone = telephone;
97	    }
98	
99	    public String getEmail() {
100	        return this.email;
101	    }
102	
103	    public void setEmail(String email) {
104	        this.email = email;
105	    }
106	
107	    public LocalDate getRegistrationDate() {
108	        return this.registrationDate;
109	    }
110	
111	    public void setRegistrationDate(LocalDate registrationDate) {
112	        this.registrationDate = registrationDate;
113	    }
114	
115	    public String getCustomerCode() {
116	        return this.customerCode;
117	    }
118	
119	    public void setCustomerCode(String customerCode) {
120	        this.customerCode = customerCode;
121	    }
122	
123	    public String getHouseholdId() {
124	        return this.householdId;
125	    }
126	
127	    public void setHouseholdId(String householdId) {
128	        this.householdId = householdId;
129	    }
130	
131	    public Integer getNamesakeCount() {
132	        return this.namesakeCount;
133	    }
134	
135	    public void setNamesakeCount(Integer namesakeCount) {
136	        this.namesakeCount = namesakeCount;
137	    }
138	
139	    public Boolean getBulkSignupWarning() {
140	        return this.bulkSignupWarning;
141	    }
142	
143	    public void setBulkSignupWarning(Boolean bulkSignupWarning) {
144	        this.bulkSignupWarning = bulkSignupWarning;
145	    }
146	
147	    /**
148	     * When no registration date is supplied, default it to the server's current date, then roll
149	     * the effective date forward onto a business day: a Saturday or Sunday becomes the following
150	     * Monday. Running on {@link PrePersist} keeps both invariants true for every create path
151	     * (any controller, bulk import or test fixture) rather than a single entry point. The roll is
152	     * idempotent, so a date already adjusted by a caller is left unchanged.
153	     */
154	    @PrePersist
155	    protected void onCreate() {
156	        this.registrationDate = BusinessDays.effectiveRegistrationDate(this.registrationDate);
157	    }
158	
159	    protected Set<Pet> getPetsInternal() {
160	        if (this.pets == null) {
161	            this.pets = new HashSet<>();
162	        }
163	        return this.pets;
164	    }
165	
166	    protected void setPetsInternal(Set<Pet> pets) {
167	        this.pets = pets;
168	    }
169	
170	    public List<Pet> getPets() {
171	        List<Pet> sortedPets = new ArrayList<>(getPetsInternal());
172	        sortedPets.sort(Comparator.comparing(Pet::getName, String.CASE_INSENSITIVE_ORDER));
173	        return Collections.unmodifiableList(sortedPets);
174	    }
175	
176	    public void setPets(List<Pet> pets) {
177	        this.pets = new HashSet<>(pets);
178	    }
179	
180	    public void addPet(Pet pet) {
181	        getPetsInternal().add(pet);
182	        pet.setOwner(this);
183	    }
184	
185	    /**
186	     * Return the Pet with the given name, or null if none found for this Owner.
187	     *
188	     * @param name to test
189	     * @return true if pet name is already in use
190	     */
191	    public Pet getPet(String name) {
192	        return getPet(name, false);
193	    }
194	
195	    /**
196	     * Return the Pet with the given name, or null if none found for this Owner.
197	     *
198	     * @param name to test
199	     * @return true if pet name is already in use
200	     */
201	    public Pet getPet(String name, boolean ignoreNew) {
202	        name = name.toLowerCase();
203	        for (Pet pet : getPetsInternal()) {
204	            if (!ignoreNew || !pet.isNew()) {
205	                String compName = pet.getName();
206	                compName = compName.toLowerCase();
207	                if (compName.equals(name)) {
208	                    return pet;
209	                }
210	            }
211	        }
212	        return null;
213	    }
214	
215	    public Pet getPet(Integer petId) {
216	        return getPetsInternal().stream().filter(p -> p.getId().equals(petId)).findFirst().orElse(null);
217	    }
218	
219	    @Override
220	    public String toString() {
221	        return new ToStringCreator(this)
222	
223	            .append("id", this.getId())
224	            .append("new", this.isNew())
225	            .append("lastName", this.getLastName())
226	            .append("firstName", this.getFirstName())
227	            .append("address", this.address)
228	            .append("city", this.city)
229	            .append("telephone", this.telephone)
230	            .append("email", this.email)
231	            .append("registrationDate", this.registrationDate)
232	            .append("customerCode", this.customerCode)
233	            .append("householdId", this.householdId)
234	            .append("namesakeCount", this.namesakeCount)
235	            .append("bulkSignupWarning", this.bulkSignupWarning)
236	            .toString();
237	    }
238	}
