38	/**
39	 * Mostly used as a facade for all Petclinic controllers
40	 * Also a placeholder for @Transactional and @Cacheable annotations
41	 *
42	 * @author Michael Isvy
43	 * @author Vitaliy Fedoriv
44	 */
45	@Service
46	public class ClinicServiceImpl implements ClinicService {
47	
48	    private final PetRepository petRepository;
49	    private final VetRepository vetRepository;
50	    private final OwnerRepository ownerRepository;
51	    private final VisitRepository visitRepository;
52	    private final SpecialtyRepository specialtyRepository;
53	    private final PetTypeRepository petTypeRepository;
54	    private final OwnerMapper ownerMapper;
55	
56	    public ClinicServiceImpl(
57	        PetRepository petRepository,
58	        VetRepository vetRepository,
59	        OwnerRepository ownerRepository,
60	        VisitRepository visitRepository,
61	        SpecialtyRepository specialtyRepository,
62	        PetTypeRepository petTypeRepository,
63	        OwnerMapper ownerMapper) {
64	        this.petRepository = petRepository;
65	        this.vetRepository = vetRepository;
66	        this.ownerRepository = ownerRepository;
67	        this.visitRepository = visitRepository;
68	        this.specialtyRepository = specialtyRepository;
69	        this.petTypeRepository = petTypeRepository;
70	        this.ownerMapper = ownerMapper;
71	    }
72	
73	    @Override
74	    @Transactional(readOnly = true)
75	    public Collection<Pet> findAllPets() throws DataAccessException {
