92	    @Transactional(readOnly = true)
93	    public Visit findVisitById(int visitId) throws DataAccessException {
94	        return findEntityById(() -> visitRepository.findById(visitId));
95	    }
96	
97	    @Override
98	    @Transactional(readOnly = true)
99	    public Collection<Visit> findAllVisits() throws DataAccessException {
100	        return visitRepository.findAll();
101	    }
102	
103	    @Override
104	    @Transactional
105	    public void deleteVisit(Visit visit) throws DataAccessException {
106	        visitRepository.delete(visit);
107	    }
108	
109	    @Override
110	    @Transactional(readOnly = true)
111	    public Vet findVetById(int id) throws DataAccessException {
112	        return findEntityById(() -> vetRepository.findById(id));
113	    }
114	
115	    @Override
116	    @Transactional(readOnly = true)
117	    public Collection<Vet> findAllVets() throws DataAccessException {
118	        return vetRepository.findAll();
119	    }
120	
121	    @Override
122	    @Transactional
123	    public void saveVet(Vet vet) throws DataAccessException {
124	        vetRepository.save(vet);
125	    }
126	
127	    @Override
128	    @Transactional
129	    public void deleteVet(Vet vet) throws DataAccessException {
