131	    }
132	
133	    @Override
134	    @Transactional(readOnly = true)
135	    public Collection<Owner> findAllOwners() throws DataAccessException {
136	        return ownerRepository.findAll();
137	    }
138	
139	    @Override
140	    @Transactional(readOnly = true)
141	    public Page<Owner> findOwners(String lastName, Pageable pageable) throws DataAccessException {
142	        if (lastName != null) {
143	            return ownerRepository.findByLastName(lastName, pageable);
144	        }
145	        return ownerRepository.findAll(pageable);
146	    }
147	
148	    @Override
149	    @Transactional
150	    public void deleteOwner(Owner owner) throws DataAccessException {
