152	    }
153	
154	    @Override
155	    @Transactional(readOnly = true)
156	    public PetType findPetTypeById(int petTypeId) {
157	        return findEntityById(() -> petTypeRepository.findById(petTypeId));
158	    }
159	
160	    @Override
161	    @Transactional(readOnly = true)
162	    public Collection<PetType> findAllPetTypes() throws DataAccessException {
163	        return petTypeRepository.findAll();
164	    }
165	
166	    @Override
167	    @Transactional
168	    public void savePetType(PetType petType) throws DataAccessException {
169	        petTypeRepository.save(petType);
170	    }
171	
172	    @Override
173	    @Transactional
174	    public void deletePetType(PetType petType) throws DataAccessException {
