176	    }
177	
178	    @Override
179	    @Transactional(readOnly = true)
180	    public Specialty findSpecialtyById(int specialtyId) {
181	        return findEntityById(() -> specialtyRepository.findById(specialtyId));
182	    }
183	
184	    @Override
185	    @Transactional(readOnly = true)
186	    public Collection<Specialty> findAllSpecialties() throws DataAccessException {
187	        return specialtyRepository.findAll();
188	    }
189	
190	    @Override
191	    @Transactional
192	    public void saveSpecialty(Specialty specialty) throws DataAccessException {
193	        specialtyRepository.save(specialty);
194	    }
195	
196	    @Override
197	    @Transactional
