210	    public Owner findOwnerById(int id) throws DataAccessException {
211	        return findEntityById(() -> ownerRepository.findById(id));
212	    }
213	
214	    @Override
215	    @Transactional(readOnly = true)
216	    public Pet findPetById(int id) throws DataAccessException {
217	        return findEntityById(() -> petRepository.findById(id));
218	    }
219	
220	    @Override
221	    @Transactional
222	    public void savePet(Pet pet) throws DataAccessException {
223	        pet.setType(findPetTypeById(pet.getType().getId()));
224	        petRepository.save(pet);
225	    }
226	
227	    @Override
228	    @Transactional
229	    public void saveVisit(Visit visit) throws DataAccessException {
230	        visitRepository.save(visit);
231	
232	    }
233	
234	    @Override
235	    @Transactional(readOnly = true)
236	    public Collection<Vet> findVets() throws DataAccessException {
237	        return vetRepository.findAll();
238	    }
239	
240	    @Override
241	    @Transactional
242	    public void saveOwner(Owner owner) throws DataAccessException {
243	        if (owner.getCustomerCode() == null) {
244	            owner.setCustomerCode(generateCustomerCode(owner));
245	        }
246	        ownerRepository.save(owner);
247	
248	    }
249	
250	    /**
251	     * Build a {@code customerCode} of the form {@code <CITY3>-<LAST3>-<NNNN>}: the upper-cased
252	     * first three letters of the owner's city, a hyphen, the upper-cased first three letters of
253	     * the owner's last name, a hyphen, and a per-city 4-digit zero-padded sequence equal to one
254	     * more than the number of owners already registered in that city (e.g. {@code TOW-SMI-0007}).
255	     */
256	    private String generateCustomerCode(Owner owner) {
257	        String city = owner.getCity() == null ? "" : owner.getCity();
258	        int sequence = (int) ownerRepository.findAll().stream()
259	            .filter(existing -> city.equalsIgnoreCase(existing.getCity()))
260	            .count() + 1;
261	        return String.format("%s-%s-%04d", prefix3(city), prefix3(owner.getLastName()), sequence);
262	    }
263	
264	    /**
265	     * The upper-cased first three letters of {@code value} (fewer if it is shorter), treating a
266	     * {@code null} value as empty. This is the shared rule behind both the CITY3 and LAST3
267	     * segments of a {@code customerCode}.
268	     */
269	    private static String prefix3(String value) {
270	        String s = value == null ? "" : value;
271	        return s.substring(0, Math.min(3, s.length())).toUpperCase();
272	    }
273	
274	    @Override
275	    @Transactional(readOnly = true)
276	    public Collection<Owner> findOwnerByLastName(String lastName) throws DataAccessException {
277	        return ownerRepository.findByLastName(lastName);
278	    }
279	
280	    @Override
281	    @Transactional(readOnly = true)
282	    public boolean isTelephoneInUse(String telephone) throws DataAccessException {
283	        String normalized = ownerMapper.normalizeTelephone(telephone);
284	        if (normalized == null) {
285	            return false;
286	        }
287	        return ownerRepository.findAll().stream()
288	            .map(existing -> ownerMapper.normalizeTelephone(existing.getTelephone()))
289	            .anyMatch(normalized::equals);
290	    }
291	
292	    @Override
293	    @Transactional(readOnly = true)
294	    public boolean isEmailInUse(String email) throws DataAccessException {
295	        String normalized = ownerMapper.normalizeEmail(email);
296	        if (normalized == null) {
297	            return false;
298	        }
299	        return ownerRepository.findAll().stream()
