77	    /**
78	     * Determine an owner's membership level, a number from {@code 1} to {@code 3} assigned on
79	     * create. It starts at {@code 1}, gains {@code 1} when an email address is present, and gains
80	     * {@code 1} when the owner has no namesakes (its {@code namesakeCount} is {@code 0}), capped at
81	     * {@code 3}. A null or absent namesake count is treated as not being zero, so it contributes
82	     * nothing. Level {@code 4} is reserved for tenure.
83	     */
84	    default Integer formatMembershipLevel(Owner owner) {
85	        if (owner == null) {
86	            return null;
87	        }
88	        int level = 1;
89	        boolean hasEmail = owner.getEmail() != null && !owner.getEmail().isEmpty();
90	        if (hasEmail) {
91	            level++;
92	        }
93	        boolean uniqueName = owner.getNamesakeCount() != null && owner.getNamesakeCount() == 0;
94	        if (uniqueName) {
95	            level++;
96	        }
97	        return Math.min(level, 3);
98	    }
