160	     * Normalize a telephone number for storage into E.164 form (see {@link E164Telephone}).
161	     * The requirement that a valid E.164 number can be formed is enforced separately by
162	     * {@code TelephoneValidation}, so for already-validated input this returns the E.164
163	     * string; it is idempotent, so re-normalizing a stored value yields the same value.
164	     * {@code @Named} keeps this out of MapStruct's automatic method selection, so it only
165	     * runs where a mapping explicitly references it via {@code qualifiedByName}.
166	     */
167	    @Named("normalizeTelephone")
168	    default String normalizeTelephone(String telephone) {
169	        return E164Telephone.normalize(telephone);
170	    }
171	
172	    /**
173	     * Normalize an email address for storage by lower-casing it, so it is persisted and
174	     * returned in a canonical form regardless of the casing supplied by the caller.
175	     * Syntactic validity is enforced separately by the {@code @Email} constraint on the DTO.
176	     * {@code @Named} keeps this out of MapStruct's automatic method selection, so it only
177	     * runs where a mapping explicitly references it via {@code qualifiedByName}.
178	     */
179	    @Named("normalizeEmail")
180	    default String normalizeEmail(String email) {
181	        return email == null ? null : email.toLowerCase();
182	    }
183	
184	    List<OwnerDto> toOwnerDtoCollection(Collection<Owner> ownerCollection);
185	
186	    Collection<Owner> toOwners(Collection<OwnerDto> ownerDtos);
187	
188	    default OwnerPageDto toOwnerPageDto(@NonNull Page<Owner> ownerPage) {
189	        OwnerPageDto ownerPageDto = new OwnerPageDto();
190	        ownerPageDto.setContent(toOwnerDtoCollection(ownerPage.getContent()));
191	        ownerPageDto.setPage(ownerPage.getNumber());
192	        ownerPageDto.setSize(ownerPage.getSize());
193	        ownerPageDto.setTotalElements(ownerPage.getTotalElements());
194	        ownerPageDto.setTotalPages(ownerPage.getTotalPages());
195	        return ownerPageDto;
196	    }
